package org.lddc.android.data.converter

import org.lddc.android.data.model.Lyrics
import org.lddc.android.data.model.LyricsLine

/**
 * ASS 输出，对应上游 LDDC/core/converter/ass.py。
 */
object AssConverter {

    private const val ASS_HEADER_1 = """[Script Info]
; Script generated by LDDC Android (port of chenmozhijin/LDDC)
; https://github.com/chenmozhijin/LDDC
"""

    private const val ASS_HEADER_2 = """ScriptType: v4.00+
Timer: 100.0000

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding"""

    private const val DIALOGUE_TEMPLATE = "Dialogue: 0,%s,%s,%s,,0,0,0,,%s\n"

    private fun ms2assTimestamp(ms: Int): String {
        val totalSeconds = ms / 1000
        var s = totalSeconds % 60
        val m = (totalSeconds % 3600) / 60
        val h = totalSeconds / 3600
        var centi = Math.round((ms % 1000) / 10.0).toInt()
        if (centi == 100) {
            centi = 0
            s += 1
        }
        return "%02d:%02d:%02d.%02d".format(h, m, s, centi)
    }

    private fun lyricsLine2AssText(line: LyricsLine): String {
        if (line.words.size == 1) {
            return line.words.filter { it.text.isNotEmpty() }.joinToString("") { it.text }
        }
        val sb = StringBuilder()
        for (word in line.words) {
            val start = word.start
            val end = word.end
            if (start == null || end == null) {
                return line.words.filter { it.text.isNotEmpty() }.joinToString("") { it.text }
            }
            val k = kotlin.math.abs(end - start) / 10
            sb.append("{\\kf").append(k).append('}').append(word.text)
        }
        return sb.toString()
    }

    fun convert(
        lyrics: Lyrics,
        dict: Map<String, List<LyricsLine>>,
        langsMapping: Map<String, Map<Int, Int>>,
        langsOrder: List<String>,
    ): String {
        val sb = StringBuilder(ASS_HEADER_1)
        lyrics.title?.let { sb.append("Title: ").append(it).append('\n') }
        sb.append(ASS_HEADER_2).append('\n')
        sb.append(dict.keys.joinToString("\n") { lang ->
            "Style: $lang,Arial,20,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,2,2,2,10,10,10,1"
        }).append('\n').append('\n')
        sb.append("[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n")

        val orig = dict["orig"] ?: return sb.toString()
        val stamps = LyricsConverter.lineTimestamps(orig, lyrics.infoDurationMs())

        val texts = LinkedHashMap<String, StringBuilder>()
        langsOrder.reversed().forEach { texts[it] = StringBuilder() }

        orig.forEachIndexed { index, origLine ->
            val (start, end) = stamps[index]
            if (start == null || end == null) return@forEachIndexed
            val lines = LrcConverter.getLyricsLines(dict, langsOrder, index, origLine, langsMapping)
            lines.forEachIndexed { i, (line, _) ->
                val lang = langsOrder.getOrNull(i) ?: return@forEachIndexed
                val bucket = texts.getOrPut(lang) { StringBuilder() }
                bucket.append(
                    DIALOGUE_TEMPLATE.format(
                        ms2assTimestamp(start),
                        ms2assTimestamp(end),
                        lang,
                        lyricsLine2AssText(line),
                    ),
                )
            }
        }

        texts.values.forEach { sb.append(it) }
        return sb.toString()
    }
}
